// Typed client for the Rig Assist API.
//
// The request and response types come from the API's OpenAPI schema (schema.d.ts is
// generated by `make ui-types`), so a renamed field in the API is a compile error here,
// not a blank screen in the demo. The UI calls the API under /api on its own origin:
// Vite's dev server or nginx forwards it to FastAPI (no CORS).

import createClient from 'openapi-fetch'
import type { components, paths } from './schema'

type Schemas = components['schemas']
export type HealthResponse = Schemas['HealthResponse']
export type DocumentList = Schemas['DocumentList']
export type DocumentResponse = Schemas['DocumentResponse']
export type SearchRequest = Schemas['SearchRequest']
export type SearchResponse = Schemas['SearchResponse']
export type SearchHit = Schemas['SearchHit']
export type SearchMode = NonNullable<SearchRequest['mode']>
export type AskRequest = Schemas['AskRequest']
export type AskResponse = Schemas['AskResponse']
export type AskCitation = Schemas['AskCitation']
export type DiagnoseRequest = Schemas['DiagnoseRequest']
export type JobCreated = Schemas['JobCreated']
export type JobResponse = Schemas['JobResponse']
export type JobStatus = JobResponse['status']
export type JobStep = Schemas['JobStep']
export type WorkOrder = Schemas['WorkOrder']
export type Cause = Schemas['Cause']
export type Citation = Schemas['Citation']

/** Any failed API call: `status` is the HTTP status, or 0 when the API couldn't be reached. */
export class ApiError extends Error {
  readonly status: number

  constructor(status: number, message: string) {
    super(message)
    this.name = 'ApiError'
    this.status = status
  }
}

interface ValidationIssue {
  loc: (string | number)[]
  msg: string
}

/** A readable message from an error body: FastAPI's `detail`, or the status. */
export function errorMessage(status: number, body: unknown): string {
  if (typeof body === 'object' && body !== null && 'detail' in body) {
    const { detail } = body as { detail: unknown }
    if (typeof detail === 'string') return detail
    if (Array.isArray(detail)) {
      // 422: [{loc: ["body", "description"], msg: "..."}] → "description: ..."
      return (detail as ValidationIssue[])
        .map((issue) => {
          const field = issue.loc.filter((part) => part !== 'body').join('.')
          return field ? `${field}: ${issue.msg}` : issue.msg
        })
        .join('; ')
    }
  }
  return `The API answered with HTTP ${status}.`
}

interface FetchResult<T> {
  data?: T
  error?: unknown
  response: Response
}

/** Await an openapi-fetch call: the data on success, an ApiError otherwise. */
async function call<T>(request: Promise<FetchResult<T>>): Promise<T> {
  let result: FetchResult<T>
  try {
    result = await request
  } catch {
    // fetch rejects (no HTTP response at all) when the server is down or unreachable.
    throw new ApiError(0, "Can't reach the API. Is it running?")
  }
  const { data, error, response } = result
  if (error !== undefined || data === undefined) {
    throw new ApiError(response.status, errorMessage(response.status, error))
  }
  return data
}

export interface ApiOptions {
  /** Where the API is mounted; default: /api on the page's own origin. */
  baseUrl?: string
  /** Replaces the browser's fetch (tests). */
  fetch?: (request: Request) => Promise<Response>
}

export function createApi({ baseUrl, fetch }: ApiOptions = {}) {
  const client = createClient<paths>({
    baseUrl: baseUrl ?? `${window.location.origin}/api`,
    // openapi-fetch keeps the fetch it is given at creation. Look the global one up at
    // call time instead, so anything that wraps fetch later (test mocks, monitoring)
    // still sees the requests.
    fetch: fetch ?? ((request: Request) => globalThis.fetch(request)),
  })
  return {
    health: () => call(client.GET('/health')),
    listDocuments: () => call(client.GET('/documents')),
    search: (body: SearchRequest) => call(client.POST('/search', { body })),
    ask: (body: AskRequest) => call(client.POST('/ask', { body })),
    diagnose: (body: DiagnoseRequest) => call(client.POST('/diagnose', { body })),
    getJob: (jobId: string) =>
      call(client.GET('/jobs/{job_id}', { params: { path: { job_id: jobId } } })),
  }
}

export type Api = ReturnType<typeof createApi>

/** URL of a manual page rendered as an image (GET /documents/{doc_id}/pages/{page}). */
export function pageImageUrl(docId: string, page: number): string {
  return `/api/documents/${encodeURIComponent(docId)}/pages/${page}`
}
